package com.minhnb.finvera_be.market.service;import com.minhnb.finvera_be.market.repository.RegimeAssessmentRepository;import java.time.*;import java.util.*;import org.springframework.data.domain.PageRequest;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
/** Published read-only regime observations for alerts. */@Service public class MarketAlertDataService{private final RegimeAssessmentRepository repo;public MarketAlertDataService(RegimeAssessmentRepository r){repo=r;}public record Observation(UUID id,LocalDate date,Instant observedAt,Instant acceptedAt,String label,Integer score,String status,String ruleVersion){}@Transactional(readOnly=true)public List<Observation> latestPair(){return repo.findByAssessmentBasisOrderByTradingDateDescAsOfDescCalculatedAtDesc("EOD",PageRequest.of(0,2)).stream().map(x->new Observation(x.getId(),x.getTradingDate(),x.getAsOf(),x.getCalculatedAt(),x.getLabel(),x.getScore(),x.getDataStatus(),x.getRuleVersion())).toList();}}
